<?php
namespace Modules\Academy\Services;
use Core\database\DB;use RuntimeException;
class ZarinpalPaymentService{
 public function start(int$actor,int$invoiceId,int$installmentId):array{$merchant=trim((string)env('ZARINPAL_MERCHANT_ID',''));if($merchant==='')throw new RuntimeException('شناسه پذیرنده زرین‌پال در تنظیمات سیستم ثبت نشده است.');[$invoice,$installment]=$this->payable($actor,$invoiceId,$installmentId);$amount=(int)round((float)$installment['amount']);if($amount<1)throw new RuntimeException('مبلغ قسط برای پرداخت معتبر نیست.');$currency=strtoupper((string)env('ZARINPAL_CURRENCY','IRT'))==='IRR'?'IRR':'IRT';$token=bin2hex(random_bytes(32));$now=date('Y-m-d H:i:s');$paymentId=(int)DB::table('academy_term_invoice_payments')->insertGetId(['invoice_id'=>$invoiceId,'installment_id'=>$installmentId,'user_id'=>$actor,'amount'=>$amount,'currency'=>$currency,'callback_token'=>$token,'status'=>'created','created_at'=>$now,'created_by'=>$actor,'updated_at'=>$now,'updated_by'=>$actor]);$callback=rtrim((string)env('APP_URL',$this->origin()),'/').'/academy/payments/zarinpal/callback?token='.rawurlencode($token);try{$result=$this->request('/pg/v4/payment/request.json',['merchant_id'=>$merchant,'amount'=>$amount,'currency'=>$currency,'callback_url'=>$callback,'description'=>'پرداخت قسط '.(int)$installment['installment_number'].' فاکتور '.$invoiceId,'metadata'=>$this->metadata($actor)]);$code=(int)($result['data']['code']??0);$authority=(string)($result['data']['authority']??'');if($code!==100||$authority==='')throw new RuntimeException($this->error($result,'ایجاد درخواست پرداخت زرین‌پال ناموفق بود.'));DB::table('academy_term_invoice_payments')->where('payment_id',$paymentId)->update(['authority'=>$authority,'status'=>'pending','gateway_code'=>$code,'requested_at'=>$now,'updated_at'=>$now]);$sandbox=filter_var(env('ZARINPAL_SANDBOX',false),FILTER_VALIDATE_BOOL);return['redirectUrl'=>($sandbox?'https://sandbox.zarinpal.com':'https://www.zarinpal.com').'/pg/StartPay/'.$authority];}catch(\Throwable$e){DB::table('academy_term_invoice_payments')->where('payment_id',$paymentId)->update(['status'=>'failed','gateway_message'=>mb_substr($e->getMessage(),0,500),'updated_at'=>date('Y-m-d H:i:s')]);throw$e;}}
 public function callback(string$token,string$authority,string$status):array{$payment=DB::table('academy_term_invoice_payments')->where('callback_token',$token)->whereNull('deleted_at')->first();if(!$payment||!hash_equals((string)($payment['authority']??''),$authority))throw new RuntimeException('شناسه تراکنش معتبر نیست.');if($payment['status']==='paid')return['success'=>true,'referenceId'=>$payment['reference_id'],'alreadyVerified'=>true];if(strtoupper($status)!=='OK'){$this->fail((int)$payment['payment_id'],'پرداخت توسط کاربر لغو شد.');return['success'=>false,'message'=>'پرداخت انجام نشد یا توسط کاربر لغو شد.'];}$merchant=trim((string)env('ZARINPAL_MERCHANT_ID',''));$result=$this->request('/pg/v4/payment/verify.json',['merchant_id'=>$merchant,'amount'=>(int)$payment['amount'],'authority'=>$authority]);$code=(int)($result['data']['code']??0);if(!in_array($code,[100,101],true)){$message=$this->error($result,'تأیید پرداخت زرین‌پال ناموفق بود.');$this->fail((int)$payment['payment_id'],$message,$code);throw new RuntimeException($message);}$data=$result['data'];$now=date('Y-m-d H:i:s');transaction(function()use($payment,$data,$code,$now){$fresh=db()->query('SELECT * FROM academy_term_invoice_payments WHERE payment_id='.(int)$payment['payment_id'].' FOR UPDATE')->fetch();if($fresh['status']==='paid')return;DB::table('academy_term_invoice_payments')->where('payment_id',(int)$payment['payment_id'])->update(['status'=>'paid','reference_id'=>(string)($data['ref_id']??''),'card_pan'=>$data['card_pan']??null,'card_hash'=>$data['card_hash']??null,'gateway_code'=>$code,'verified_at'=>$now,'updated_at'=>$now]);DB::table('academy_branch_course_term_invoice_installments')->where('term_invoice_installment_id',(int)$payment['installment_id'])->where('invoice_id',(int)$payment['invoice_id'])->update(['status'=>'paid','paid_at'=>$now,'updated_at'=>$now,'updated_by'=>(int)$payment['user_id']]);$remaining=DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',(int)$payment['invoice_id'])->whereNull('deleted_at')->where('status','<>','paid')->count();$paid=DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',(int)$payment['invoice_id'])->whereNull('deleted_at')->where('status','paid')->count();DB::table('academy_branch_course_term_invoices')->where('term_invoice_id',(int)$payment['invoice_id'])->update(['status'=>$remaining===0?'paid':($paid>0?'partial':'issued'),'updated_at'=>$now,'updated_by'=>(int)$payment['user_id']]);});return['success'=>true,'referenceId'=>(string)($data['ref_id']??''),'alreadyVerified'=>$code===101];}
 private function payable(int$a,int$iid,int$sid):array{$invoice=DB::table('academy_branch_course_term_invoices')->where('term_invoice_id',$iid)->whereNull('deleted_at')->first();$installment=DB::table('academy_branch_course_term_invoice_installments')->where('term_invoice_installment_id',$sid)->where('invoice_id',$iid)->whereNull('deleted_at')->first();if(!$invoice||!$installment)throw new RuntimeException('فاکتور یا قسط یافت نشد.');$term=DB::table('academy_branch_course_terms')->where('term_id',(int)$invoice['term_id'])->whereNull('deleted_at')->first();$course=$term?DB::table('academy_branch_courses')->where('course_id',(int)$term['course_id'])->whereNull('deleted_at')->first():null;if(!$course||(new AcademyTermService())->invoiceBootstrap($a)===[])throw new RuntimeException('دسترسی به فاکتور ندارید.');$allowed=array_column((new AcademyTermService())->invoiceBootstrap($a)['invoices']??[],'id');if(!in_array($iid,$allowed,true))throw new RuntimeException('دسترسی به این فاکتور ندارید.');if($installment['status']==='paid')throw new RuntimeException('این قسط قبلاً پرداخت شده است.');$first=DB::table('academy_branch_course_term_invoice_installments')->where('invoice_id',$iid)->whereNull('deleted_at')->where('status','<>','paid')->orderBy('installment_number')->orderBy('term_invoice_installment_id')->first();if(!$first||(int)$first['term_invoice_installment_id']!==$sid)throw new RuntimeException('ابتدا قسط قبلی را پرداخت کنید.');return[$invoice,$installment];}
 private function request(string$path,array$data):array{$sandbox=filter_var(env('ZARINPAL_SANDBOX',false),FILTER_VALIDATE_BOOL);$host=$sandbox?'https://sandbox.zarinpal.com':'https://api.zarinpal.com';$ch=curl_init($host.$path);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>30,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Accept: application/json'],CURLOPT_USERAGENT=>'Sornaz-ZarinPal/1.0']);$raw=curl_exec($ch);$error=curl_error($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($raw===false||$error)throw new RuntimeException('ارتباط با زرین‌پال برقرار نشد: '.$error);$result=json_decode($raw,true);if(!is_array($result))throw new RuntimeException('پاسخ نامعتبر از زرین‌پال دریافت شد.');if($http<200||$http>=300)throw new RuntimeException($this->error($result,'خطای ارتباط با زرین‌پال ('.$http.').'));return$result;}
 private function fail(int$id,string$message,int$code=0):void{DB::table('academy_term_invoice_payments')->where('payment_id',$id)->update(['status'=>'failed','gateway_code'=>$code?:null,'gateway_message'=>mb_substr($message,0,500),'updated_at'=>date('Y-m-d H:i:s')]);}private function error(array$r,string$f):string{return(string)($r['errors']['message']??$r['data']['message']??$f);}private function metadata(int$id):array{$user=$this->user($id);$metadata=[];$mobile=trim((string)($user['phone']??''));$email=trim((string)($user['email']??''));if($mobile!=='')$metadata['mobile']=$mobile;if($email!==''&&filter_var($email,FILTER_VALIDATE_EMAIL))$metadata['email']=$email;return$metadata;}private function user(int$id):array{return DB::table('users')->where('user_id',$id)->first()?:[];}private function origin():string{$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';return$scheme.'://'.($_SERVER['HTTP_HOST']??'localhost');}
}
